      "stem": "A task's priority is stored as an `int` where 2, 1 and 0 mean high, medium and low. What is the main benefit of replacing it with an enumeration `Priority { HIGH, MEDIUM, LOW }`?",
      "options": [
        {
          "key": "A",
          "text": "Enumerations use less memory than integers",
          "correct": false
        },
        {
          "key": "B",
          "text": "The variable can no longer be assigned an invalid value, because the compiler catches it",
          "correct": true
        },
        {
          "key": "C",
          "text": "Enumerations can be compared faster than integers",
          "correct": false
        },
        {
          "key": "D",
          "text": "The priority can then be changed at run time by the user",
          "correct": false
        }
      ],
      "explanation": "An enumeration is a fixed set of values that can be considered a data type. With `int`, an invalid value such as 9 could be assigned; with an enum the compiler rejects anything outside the set.",
      "optional": false
