      "subtopic": "Advantages of use cases",
      "basis": "bold",
      "ab3": [],
      "stem": "Which are advantages of documenting requirements as use cases? (Select all that apply.)",
      "options": [
        {
          "key": "A",
          "text": "They use a simple notation and plain English, so users can understand them and give feedback",
          "correct": true
        },
        {
          "key": "B",
          "text": "They decouple user intention from mechanism, leaving designers freedom over the UI",
          "correct": true
        },
        {
          "key": "C",
          "text": "Identifying extensions encourages considering all situations",
          "correct": true
        },
        {
          "key": "D",
          "text": "They are well suited to capturing requirements that do not involve user interaction",
          "correct": false
        }
      ],
      "explanation": "The last statement is the main disadvantage: use cases are not good for requirements without a user interacting with the system, so they should not be the sole means of specifying requirements.",
      "optional": false
