        {
          "key": "C",
          "text": "Test `isAbsent` true with every exam score",
          "correct": false
        },
        {
          "key": "D",
          "text": "Add a case with `isAbsent` true and a non-zero score expecting an error, and keep `isAbsent` false in the cases that test other exam scores",
          "correct": true
        }
